// Generate / refresh the native iOS Capacitor project (task 083).
//
// Runs on any OS: `cap add ios` COPIES the platform template (pure file copy,
// identical output on Windows and macOS) and then `cap sync` copies the web
// build into it. The ONLY macOS-specific step is `pod install` (CocoaPods),
// which writes the git-ignored Pods/ + App.xcworkspace and is regenerated by CI
// on the macOS runner — so its failure here is expected and non-fatal.
//
// Usage: node tools/cap-bootstrap.mjs   (run `npm run build` first so dist/ exists)
import { execSync } from 'child_process';
import { existsSync } from 'fs';
import { join } from 'path';

const root = join(process.cwd());
const hasIos = existsSync(join(root, 'ios', 'App', 'App.xcodeproj'));
const cmd = hasIos ? 'sync ios' : 'add ios';

// CI=true forces the Capacitor CLI non-interactive (no prompts on a headless host).
const env = { ...process.env, CI: 'true' };
console.log(`[cap-bootstrap] ios/ ${hasIos ? 'exists -> cap sync' : 'missing -> cap add'}`);
try {
  execSync(`npx --no-install cap ${cmd}`, { stdio: 'inherit', shell: true, env });
} catch (e) {
  // pod install / xcode steps fail off macOS; the scaffold is already written.
  console.log(`[cap-bootstrap] cap ${cmd} returned non-zero (expected off macOS: CocoaPods). Continuing.`);
}

const ok = existsSync(join(root, 'ios', 'App', 'App.xcodeproj', 'project.pbxproj'));
console.log(`[cap-bootstrap] ios/App/App.xcodeproj present: ${ok}`);
if (!ok) { console.error('[cap-bootstrap] FAILED: native project was not scaffolded'); process.exit(1); }
